'use strict';
// Opt-in local diagnostics; nothing is uploaded. CPU timings are not GPU completion timings.
const Debug=(()=>{
let pixel=false,opened=false,running=false,samples=[],live=[],last=0,lastPaint=0,phase=-1,began=0,results=[],original=false,originalMode='',nextUi=0;
const order=[false,true,true,false],warmup=1500,duration=7500;
const mean=a=>a.length?a.reduce((s,v)=>s+v,0)/a.length:0;
const percentile=(a,p)=>{const s=a.slice().sort((a,b)=>a-b);return s.length?s[Math.min(s.length-1,Math.floor((s.length-1)*p))]:0};
function stats(rows){const paints=rows.filter(r=>r.paint);const times=rows.map(r=>r.frame);return{samples:rows.length,painted:paints.length,frameMean:mean(times),frameP95:percentile(times,.95),renderMean:mean(paints.map(r=>r.render)),renderP95:percentile(paints.map(r=>r.render),.95),workMean:mean(rows.map(r=>r.work)),longFrames:times.filter(t=>t>50).length,canvas:canvas.width+'×'+canvas.height}}
function show(r){return `rAF ${r.frameMean.toFixed(2)} ms · p95 ${r.frameP95.toFixed(2)} ms\nRender CPU ${r.renderMean.toFixed(3)} ms · p95 ${r.renderP95.toFixed(3)} ms\nJS frame work ${r.workMean.toFixed(3)} ms · >50ms frames ${r.longFrames}/${r.samples}\nPainted ${r.painted} frames · canvas ${r.canvas}`}
function panel(){return document.getElementById('debugPanel')}
function observe(frame,renderMs,work,paint){if(!opened||running)return;if(frame>0&&frame<1000){live.push({frame,render:renderMs,work,paint});if(live.length>600)live.shift()}const now=performance.now();if(now>nextUi){nextUi=now+1000;document.getElementById('debugLive').textContent=show(stats(live))}}
function setPixel(value){pixel=value;document.body.classList.toggle('pixel-mode',pixel);resize();const b=document.getElementById('debugPixel');if(b)b.textContent=pixel?'PIXEL MODE: ON':'PIXEL MODE: OFF'}
function stop(message){if(!running)return;running=false;setPixel(original);P.setMode(originalMode);last=performance.now();document.getElementById('debugRun').disabled=false;if(message)document.getElementById('debugReport').textContent=message;}
function startBenchmark(){if(state!=='playing'||typeof V!=='undefined'&&V.active){document.getElementById('debugReport').textContent='Start a solo mission first. Live co-op cannot be frozen for a benchmark.';return}running=true;original=pixel;originalMode=P.mode;P.setMode('eco');results=[];phase=-1;document.getElementById('debugRun').disabled=true;advance(performance.now())}
function advance(t){phase++;samples=[];began=last=t;lastPaint=-Infinity;if(phase>=4){const report={kind:'Frozen scene rendering benchmark (not full gameplay)',mission:typeof Intro!=='undefined'&&Intro.active?Intro.title:C.world+'/'+C.level,viewport:W+'×'+H,dpr:devicePixelRatio,quality:'eco',order:['normal','pixel','pixel','normal'],segments:results};let text=report.kind+'\nSame scene, fixed Eco 30 FPS; 1.5s warmup + 6s sample per segment.\n';results.forEach((r,i)=>text+=`\n${i+1}. ${order[i]?'PIXEL':'NORMAL'}\n${show(r)}\n`);const normal=mean([results[0].renderMean,results[3].renderMean]),low=mean([results[1].renderMean,results[2].renderMean]);text+=`\nRender CPU change: ${normal?((low/normal-1)*100).toFixed(1):'N/A'}%. GPU work is not measured.\n${normal<1?'Drawing submissions are already cheap here; pixel mode is not established as a fix for the reported slowdown.':'Compare frame p95 and repeat on the affected phone before choosing an art conversion.'}`;document.getElementById('debugReport').textContent=text;document.getElementById('debugData').value=JSON.stringify(report,null,2);stop();return}setPixel(order[phase]);document.getElementById('debugReport').textContent=`RUNNING ${phase+1}/4 · ${order[phase]?'PIXEL':'NORMAL'}\nSimulation is frozen so the mission, cars and effects are identical. Keep this tab visible.`}
function frame(t){if(!running)return;const frame=t-last;last=t;const begin=performance.now();const paint=t-lastPaint>=1000/30-.5;let renderMs=0;if(paint){const b=performance.now();render();renderMs=performance.now()-b;lastPaint=t}if(t-began>=warmup&&frame>0)samples.push({frame,render:renderMs,work:performance.now()-begin,paint});if(t-began>=duration){results.push(stats(samples));advance(t)}}
function init(){if(typeof location==='undefined'||!/[?&]debug(=|&|$)/.test(location.search))return;const b=document.createElement('button');b.textContent='DEBUG';b.id='debugButton';b.onclick=()=>{opened=!opened;panel().hidden=!opened;live=[]};document.querySelector('.actions').append(b);const p=document.createElement('section');p.id='debugPanel';p.hidden=true;p.innerHTML='<b>LOCAL RENDER DIAGNOSTICS</b><button id="debugClose">CLOSE</button><pre id="debugLive">Start a mission for live timings.</pre><button id="debugPixel">PIXEL MODE: OFF</button><button id="debugRun">COMPARE SAME SCENE · 30 SEC</button><button id="debugAudit">SIMULATE 500 LEVELS · NO REWARDS</button><button id="debugStop">CANCEL COMPARISON</button><pre id="debugReport">Normal versus 240px short-edge pixel canvas. Dialogue and controls stay sharp. CPU submission time excludes GPU completion. Comparison freezes gameplay; it does not measure AI or collision cost.</pre><details><summary>Copy report JSON</summary><textarea id="debugData" readonly aria-label="Benchmark report JSON"></textarea></details>';document.body.append(p);document.getElementById('debugAudit').onclick=()=>Audit.begin();document.getElementById('debugClose').onclick=()=>{stop('Cancelled');opened=false;p.hidden=true};document.getElementById('debugPixel').onclick=()=>{if(!running)setPixel(!pixel)};document.getElementById('debugRun').onclick=startBenchmark;document.getElementById('debugStop').onclick=()=>stop('Cancelled; original graphics restored.');document.addEventListener('visibilitychange',()=>{if(document.hidden)stop('Comparison cancelled: tab hidden. Repeat with the tab visible.')});addEventListener('resize',()=>stop('Comparison cancelled: viewport changed.'));}
return{init,observe,frame,get pixel(){return pixel},get running(){return running},cancel:()=>stop('Cancelled: mission changed.')};
})();
